/**
 * Test Case: JSON Schema Validation
 *
 * Tags: @master @regression @api
 *
 * Covers prompts 29-31: product, user and cart response schemas
 * (schemas are stored in api/schemas/).
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '@playwright/test';
import Ajv from 'ajv';
import dotenv from 'dotenv';
import { Routes } from '../../api/endpoints/routes';
import { DataProvider } from '../../utils/DataReader';

dotenv.config({ override: true });

test.describe('Schema Validation API Tests', () => {

    // ---------------------------------------------------------
    // Configuration
    // ---------------------------------------------------------

    const BASE_URL = process.env.API_BASE_URL || Routes.BASE_URL;
    const PRODUCT_ID = Number(process.env.PRODUCT_ID ?? 1);
    const USER_ID = Number(process.env.USER_ID ?? 1);
    const CART_ID = Number(process.env.CART_ID ?? 1);

    const ajv = new Ajv({ allErrors: true });

    /**
     * Validates data against a JSON schema file and returns readable errors.
     * @param schemaPath - Path to the schema file under api/schemas
     * @param data - Response body to validate
     * @returns Validation errors as text (empty when valid)
     */
    function validateSchema(schemaPath: string, data: unknown): string {
        const validate = ajv.compile(DataProvider.readJson(schemaPath));
        const isValid = validate(data);
        if (!isValid) {
            console.log('Schema validation errors:', validate.errors);
        }
        return isValid ? '' : ajv.errorsText(validate.errors);
    }

    // ---------------------------------------------------------
    // GET - Schema Checks
    // ---------------------------------------------------------

    test('GET - Product Response Schema @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_PRODUCT_BY_ID.replace('{id}', String(PRODUCT_ID))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get product should return 200').toBe(200);

        const errors = validateSchema('./api/schemas/product_api_schema.json', await response.json());
        expect(errors, `Product response should match the schema: ${errors}`).toBe('');
    });

    test('GET - User Response Schema @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_USER_BY_ID.replace('{id}', String(USER_ID))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get user should return 200').toBe(200);

        const errors = validateSchema('./api/schemas/user_api_schema.json', await response.json());
        expect(errors, `User response should match the schema: ${errors}`).toBe('');
    });

    test('GET - Cart Response Schema @master @regression @api', async ({ request }) => {
        const url = `${BASE_URL}${Routes.GET_CART_BY_ID.replace('{id}', String(CART_ID))}`;
        const response = await request.get(url);

        expect(response.status(), 'Get cart should return 200').toBe(200);

        const errors = validateSchema('./api/schemas/cart_api_schema.json', await response.json());
        expect(errors, `Cart response should match the schema: ${errors}`).toBe('');
    });
});
